import {esc,scoreSummary,consultantFinding,actionSuggestions,diagnosticDraft,legacyDiagnosticDraft} from './model.js';
export const consultingSources={
 coaching:{title:'Gallup · A Great Manager’s Most Important Habit',url:'https://www.gallup.com/workplace/505370/great-manager-important-habit.aspx',principle:'Retours réguliers, reconnaissance précise et clarification des priorités ; les associations observées ne garantissent pas un effet causal en CHR.'},
 discovery:{title:'Salesforce · What Is Consultative Sales?',url:'https://www.salesforce.com/blog/sales/consultative-sales-approach/',principle:'Guide professionnel : écouter et qualifier les besoins avant de proposer une solution ; son effet doit être testé localement.'},
 feedback:{title:'Bain · Closing the Loop',url:'https://www.netpromotersystem.com/insights/rob-markey-closing-the-loop-nps-video/',principle:'Relier le retour client à une réponse, un responsable et une correction ; la satisfaction déclarée ne mesure pas seule la fidélité.'},
 improvement:{title:'IHI · Model for Improvement',url:'https://www.ihi.org/library/model-for-improvement',principle:'Définir un objectif, une mesure et un test PDSA limité ; adaptation HP d’un cadre diffusé notamment en santé.'},
 management:{title:'Amy Edmondson · Psychological Safety and Learning Behavior in Work Teams (1999)',url:'https://dash.harvard.edu/entities/publication/13a7b031-0fdd-45ec-a7e0-2b80e2bc679f',principle:'La recherche associe la sécurité psychologique aux comportements d’apprentissage en équipe. Son contexte industriel invite à adapter les pratiques au terrain CHR.'},
 integration:{title:'France Travail · Le rôle du manager dans l’intégration d’un salarié',url:'https://www.francetravail.fr/employeur/vos-recrutements/integrer-un-nouveau-salarie/le-role-du-manager-dans-lintegra.html',principle:'Repères retenus : transmission des méthodes, participation de l’équipe, points d’étape et écoute du nouvel arrivant.'},
 prevention:{title:'INRS · Nouveaux embauchés : ce qu’il faut retenir',url:'https://www.inrs.fr/demarche/nouveaux-embauches/ce-qu-il-faut-retenir',principle:'L’accueil et l’accompagnement au poste contribuent à la prévention des risques lors de l’intégration.'},
 sales:{title:'Bpifrance Création · Conclure une vente : 13 règles d’or',url:'https://bpifrance-creation.fr/encyclopedie/developper-lactivite-son-entreprise/vendre-negocier/conclure-vente-13-regles-dor',principle:'Repères retenus : qualifier le besoin, écouter, reformuler les objections et convenir de la prochaine étape.'},
 acquisition:{title:'Bpifrance Création · Comment trouver les clients de mon entreprise ?',url:'https://bpifrance-creation.fr/moments-de-vie/comment-trouver-clients-mon-entreprise',principle:'Définir une clientèle cible et organiser le suivi des canaux et du cycle commercial.'},
 loyalty:{title:'Cornell · McCall, Voorhees et Calantone · Building Customer Loyalty (2010)',url:'https://ecommons.cornell.edu/entities/publication/64e29784-eded-4e4e-b3e8-c17c4e8b2777',principle:'Un programme de récompense ne garantit pas la fidélité. Son utilité doit être mesurée et son fonctionnement adapté aux clients.'},
 revenue:{title:'Cornell · Kimes, Barrash et Alexander · Developing a Restaurant Revenue-management Strategy (1999)',url:'https://ecommons.cornell.edu/entities/publication/897385c1-31d1-4c47-a731-22e1e7935e17',principle:'Cette étude de restaurant illustre une démarche d’analyse, d’expérimentation et de suivi des résultats. Ses résultats ne constituent pas une promesse pour cet établissement.'}
};
// Propositions méthodologiques originales HP : les causes proposées doivent être
// confrontées aux faits. Les sources étayent des principes, pas un résultat garanti.
const profiles={
 H1:{aim:'Permettre à l’équipe de décider dans un cadre clair, tout en réservant au dirigeant les arbitrages qui engagent réellement l’établissement.',mechanism:'Une responsabilité déléguée sans limite de décision, moyen disponible ou relais identifié reste souvent théorique. Le point à examiner est la capacité de l’équipe à agir lorsque le responsable habituel est occupé ou absent.',causes:['Décisions courantes conservées par habitude au niveau du dirigeant.','Limites d’autonomie différentes selon les personnes ou les services.','Relais non préparé ou moyens insuffisants pour assumer la délégation.'],questions:['Quelles décisions courantes remontent encore au dirigeant et pourquoi ?','Que peut décider chaque responsable sans demander d’accord ?','Comment le relais fonctionne-t-il lors d’une absence ou d’un pic d’activité ?'],steps:['Relever pendant une semaine les sollicitations du dirigeant ; distinguer arbitrages utiles, demandes d’information et validations répétitives.','Définir avec l’équipe une matrice : décision, titulaire, relais, limite d’autonomie et situation nécessitant un arbitrage.','Tester le cadre sur un service puis sur une absence préparée ; revoir les limites qui créent une hésitation ou une prise de risque.'],metric:'Nombre de sollicitations pour validation courante ÷ nombre de services observés. Séparer les arbitrages légitimes des demandes évitables.',tool:'Décision | responsable | relais | limite d’autonomie | moyen disponible | règle d’escalade',example:'Autoriser le responsable de service à réaffecter les postes dans un cadre défini ; conserver l’arbitrage d’une dépense exceptionnelle au dirigeant.',owner:'Dirigeant et responsables de service',sources:['management']},
 H2:{aim:'Installer des temps courts qui relient objectifs, difficultés de service et décisions effectivement suivies.',mechanism:'Un brief transmet des informations ; une routine de management doit aussi permettre de traiter les obstacles et de vérifier les engagements. L’analyse porte sur la continuité entre le point d’équipe, le service et le suivi des décisions.',causes:['Réunions centrées sur les consignes sans espace pour les difficultés.','Décisions sans responsable ni échéance.','Temps de suivi supprimé dès que la charge augmente.'],questions:['Quelles décisions du dernier point d’équipe ont été appliquées ?','Les salariés peuvent-ils signaler un obstacle avant qu’il dégrade le service ?','Quel temps est réservé au suivi des engagements ?'],steps:['Observer un brief et un débrief ; distinguer informations utiles, décisions, problèmes non traités et sujets à arbitrer.','Tester un brief de 5 à 10 minutes et un point hebdomadaire de 20 minutes : objectif, obstacle, décision, responsable, échéance.','Relire chaque semaine les engagements ; reconnaître les progrès et résoudre les obstacles avant d’ajouter de nouveaux objectifs.'],metric:'Décisions réalisées à l’échéance ÷ décisions arrivées à échéance × 100. Compléter par le nombre de difficultés restées sans réponse.',tool:'Objectif du service | obstacle signalé | décision | responsable | échéance | retour à l’équipe',example:'Après deux services avec une attente au bar, tester une nouvelle répartition des prises de commande puis demander le retour du bar et de la salle.',owner:'Responsable d’exploitation et managers de proximité',sources:['management']},
 H3:{aim:'Assurer qu’une information utile au service est reçue, comprise et retrouvable par les personnes concernées.',mechanism:'Multiplier les canaux ne garantit pas une meilleure transmission. Le risque se situe aux changements d’équipe, aux mises à jour de dernière minute et aux consignes qui ne donnent ni responsable ni action attendue.',causes:['Consignes dispersées entre messages, oral et documents.','Passation laissée à la mémoire de chacun.','Absence de vérification de compréhension pour les informations sensibles.'],questions:['Où trouve-t-on la dernière version d’un brief ou d’une consigne ?','Comment une modification tardive est-elle transmise aux personnes absentes ?','Qui vérifie les informations critiques avant le début du service ?'],steps:['Suivre trois informations de leur émission à leur utilisation : groupe attendu, changement de carte et incident à traiter.','Choisir un canal de référence et une trame de passation : ce qui change, qui agit, quand, points de vigilance et version.','Tester la passation sur deux rotations d’équipe ; demander aux destinataires de reformuler les points critiques et corriger les ambiguïtés.'],metric:'Consignes critiques correctement appliquées ÷ consignes critiques vérifiées × 100. Noter la cause des écarts plutôt que le seul nom de la personne.',tool:'Date et version | information | personnes concernées | action attendue | point critique | réception vérifiée',example:'Un changement d’effectif d’un groupe est mis à jour dans le brief de référence ; salle, bar et cuisine confirment la nouvelle organisation.',owner:'Manager de service et référent du canal commun',sources:['management']},
 H4:{aim:'Rendre l’intégration reproductible et sécuriser l’autonomie progressive des nouveaux collaborateurs, y compris saisonniers et extras.',mechanism:'L’expérience antérieure ne suffit pas à connaître les standards du lieu. Une intégration informelle peut transmettre des habitudes contradictoires et laisser le nouvel arrivant seul face à une difficulté qu’il n’ose pas signaler.',causes:['Accueil réduit à une présentation rapide avant le service.','Référent désigné sans temps réservé à l’accompagnement.','Autonomie supposée à partir de l’ancienneté plutôt que vérifiée en situation.'],questions:['Que doit maîtriser un nouvel arrivant au premier service, à J7 et à J30 ?','Qui démontre les gestes, observe leur réalisation et répond aux questions ?','Quels retours du nouvel arrivant ont conduit à modifier le parcours ?'],steps:['Construire une fiche d’accueil : fonctionnement du lieu, interlocuteurs, standards essentiels, sécurité au poste et situations nécessitant une aide.','Préparer un parcours J1/J7/J30 avec un référent disponible ; démontrer les tâches puis observer la réalisation sur des situations adaptées.','Faire un point de 15 minutes : ce qui est acquis, ce qui reste difficile et l’aide nécessaire ; adapter le parcours sans exposer la personne devant l’équipe.'],metric:'Étapes du parcours réalisées et vérifiées ÷ étapes prévues à la date du point × 100. Suivre séparément les compétences encore à accompagner.',tool:'Compétence | démonstration réalisée | pratique accompagnée | réalisation observée | aide nécessaire | prochain point',example:'Avant un service chargé, un nouveau serveur réalise une prise de commande accompagnée puis une passation au bar ; le référent vérifie les points critiques.',owner:'Manager, référent d’intégration et nouveau collaborateur',sources:['integration','prevention','management']},
 P1:{aim:'Comprendre ce qui fait évoluer l’activité et transformer les chiffres disponibles en décisions commerciales ou opérationnelles.',mechanism:'Un total de chiffre d’affaires masque les effets de fréquentation, de panier moyen et de composition des ventes. La priorité est de comparer des périodes réellement comparables avant d’attribuer une variation à une action.',causes:['Périodes ou périmètres de comparaison différents.','Absence de suivi du nombre de couverts ou de transactions.','Événements exceptionnels confondus avec l’activité courante.'],questions:['Les montants comparés sont-ils tous HT ou tous TTC ?','La variation vient-elle du nombre de clients ou du panier moyen ?','Quels événements, horaires ou fermetures expliquent les écarts ?'],steps:['Fixer un périmètre commun : site, activité, période, HT/TTC et distinction entre restauration, bar et événements.','Consolider une semaine type : CA, couverts ou transactions, panier moyen et contexte du service ; documenter les données manquantes.','Tester une décision sur un créneau comparable et suivre simultanément activité, qualité de service et charge de l’équipe.'],metric:'Ticket moyen = CA du périmètre ÷ nombre de couverts ou transactions du même périmètre. Préciser le dénominateur choisi et conserver la même définition.',tool:'Date | service | CA | couverts ou transactions | ticket moyen | contexte | décision',example:'Comparer deux services du jeudi avec des horaires similaires ; isoler un groupe exceptionnel au lieu de conclure à une progression générale.',owner:'Dirigeant et responsable du suivi d’activité',sources:['revenue']},
 P2:{aim:'Identifier les offres dont le coût est connu et les écarts qui nécessitent un contrôle, avant de modifier prix ou portions.',mechanism:'Le coût matière dépend des prix d’achat, rendements, portions, pertes et produits offerts. Une hausse des achats ne suffit pas à démontrer une baisse de marge : stocks et période de consommation doivent être rapprochés.',causes:['Fiches techniques non actualisées.','Portions ou rendements variables.','Achats et consommations comparés sur des périodes différentes.'],questions:['Quels produits concentrent les volumes et les incertitudes de coût ?','Les portions réelles correspondent-elles aux fiches techniques ?','Les pertes, offerts et variations de stock sont-ils distingués ?'],steps:['Choisir cinq offres représentatives et relever ingrédients, quantités, rendement et dernier prix d’achat ; indiquer les données inconnues.','Observer la préparation et le service pour comparer portions théoriques et réalisées ; rechercher les causes avant toute réduction.','Actualiser les fiches et tester une correction ciblée : approvisionnement, préparation ou standard de portion ; vérifier l’acceptation client.'],metric:'Coût matière théorique par portion = somme des quantités utilisées × coûts unitaires corrigés du rendement. Un ratio réel exige des consommations et un CA cohérents.',tool:'Produit | quantité | coût unitaire | rendement | coût par portion | date de mise à jour',example:'Sur un cocktail phare, vérifier la quantité versée, le rendement du jus et le coût des garnitures avant de modifier son prix.',owner:'Dirigeant, chef de cuisine ou responsable bar',sources:['revenue']},
 P3:{aim:'Ajuster les heures mobilisées à l’activité tout en protégeant la qualité du service et les conditions de travail.',mechanism:'Un ratio de productivité peut signaler un écart mais ne décrit pas toute la charge : préparation, nettoyage, accueil de groupes et niveau de service doivent être pris en compte. Le suivi sert à discuter l’organisation réelle.',causes:['Heures et CA issus de périmètres différents.','Temps de préparation ou tâches invisibles oubliés.','Comparaison de services aux besoins très différents.'],questions:['Quelles tâches sont nécessaires avant et après le service ?','Le ratio inclut-il les mêmes équipes et activités sur chaque période ?','À quel moment l’équipe signale-t-elle une surcharge ou une sous-charge ?'],steps:['Rapprocher heures réellement travaillées et activité sur deux semaines, en conservant les temps de préparation et de fermeture.','Identifier les créneaux à examiner avec l’équipe ; distinguer attente, manque de coordination et charge incompressible.','Tester un changement limité de couverture ou de répartition des tâches et contrôler les délais de service, incidents et retours de l’équipe.'],metric:'CA par heure travaillée = CA d’un périmètre ÷ heures travaillées de ce même périmètre. Suivre aussi un indicateur de qualité et un retour de charge.',tool:'Service | heures prévues | heures réalisées | activité | tâches particulières | charge perçue | ajustement',example:'Un service de groupe peut nécessiter davantage de préparation ; son ratio est comparé avec un autre groupe similaire, pas avec un service ordinaire.',owner:'Responsable d’exploitation et responsables de planning',sources:['revenue','management']},
 P4:{aim:'Limiter le tableau de bord aux indicateurs qui conduisent à un arbitrage utile et à une action suivie.',mechanism:'Un indicateur sans définition, propriétaire ou décision associée produit une impression de contrôle. La priorité est de rendre les écarts discutables et de vérifier que la décision choisie traite la cause réelle.',causes:['Trop de chiffres sans priorité de lecture.','Définitions variables selon les personnes.','Revue d’indicateurs sans compte rendu des décisions.'],questions:['Quelle décision peut être prise à partir de chaque indicateur ?','Qui produit le chiffre et vérifie sa fiabilité ?','Quels écarts ont réellement entraîné un changement de pratique ?'],steps:['Choisir quatre indicateurs utiles : activité, qualité, charge de travail et avancement d’une priorité ; préciser leurs limites.','Créer une fiche par indicateur : définition, source, fréquence, responsable et situation qui déclenche une revue.','Tenir une revue courte chaque semaine : écart, explication à vérifier, décision, responsable et date de contrôle.'],metric:'Revues avec décision suivie ÷ revues prévues × 100. Mesurer aussi la part des indicateurs dont la source et la définition sont documentées.',tool:'Indicateur | définition | source | tendance | explication | décision | responsable | contrôle',example:'Une baisse de conversion entraîne une lecture des dossiers perdus avant un changement de prix ou une augmentation des dépenses publicitaires.',owner:'Dirigeant et responsables des indicateurs',sources:['revenue','management']},
 G1:{aim:'Concentrer l’effort commercial sur des segments et des canaux dont l’utilité peut être vérifiée.',mechanism:'La visibilité ne se transforme pas automatiquement en demandes pertinentes. L’analyse doit suivre le parcours depuis le canal d’origine jusqu’à la demande qualifiée et à la vente, avec une offre adaptée à la cible.',causes:['Cible trop large ou offre peu lisible.','Origine des demandes non renseignée.','Canaux choisis par habitude sans comparaison des résultats.'],questions:['Quels clients sont recherchés, sur quels créneaux et pour quelles offres ?','D’où viennent les demandes qui se transforment réellement ?','Le temps consacré à chaque canal est-il connu ?'],steps:['Définir deux segments prioritaires avec occasion de visite, besoin, période et proposition adaptée ; vérifier leur cohérence avec la capacité du lieu.','Tester deux canaux pendant quatre semaines et relever origine, besoin, qualification, prochaine étape et issue de chaque demande.','Comparer qualité des demandes et effort mobilisé ; conserver, modifier ou arrêter chaque test à partir des dossiers effectivement suivis.'],metric:'Taux de qualification par canal = demandes correspondant à la cible ÷ demandes reçues sur le canal × 100. Suivre séparément ventes et temps commercial.',tool:'Canal | cible | offre | effort mobilisé | demandes | demandes qualifiées | ventes | décision',example:'Pour développer les groupes en semaine, comparer un partenariat hôtelier et une prospection ciblée d’entreprises, avec la même offre de référence.',owner:'Responsable commercial ou dirigeant',sources:['acquisition','sales']},
 G2:{aim:'Sécuriser chaque demande commerciale et aider le client à prendre une décision éclairée sur une offre adaptée.',mechanism:'Un devis envoyé ne clôt pas le travail commercial. La progression dépend de la compréhension du besoin, de la lisibilité de la proposition et d’une prochaine étape convenue. Une relance générique renseigne peu sur le blocage réel.',causes:['Besoins, budget ou décideur mal identifiés.','Offre décrite par ses composants sans bénéfice ni contraintes claires.','Devis sans prochaine étape ou dossier sans responsable.'],questions:['Le besoin, le décideur, la date et les critères de choix sont-ils identifiés ?','La prochaine étape a-t-elle été convenue avec le client ?','Les dossiers perdus sont-ils classés par motif vérifié ?'],steps:['Auditer dix demandes récentes : délai de réponse, qualification, devis, prochaine étape, issue et motif de perte ; ne pas inventer les motifs inconnus.','Tester une trame de découverte : occasion, participants, attentes, budget, contraintes, décideur et échéance ; reformuler avant de proposer.','Suivre les dossiers dans un tableau unique et relancer selon l’échéance convenue, en posant une question utile sur le point restant à décider.'],metric:'Taux de transformation = devis signés ÷ devis ayant une issue connue × 100, par cohorte de demandes. Afficher séparément les dossiers encore ouverts.',tool:'Demande | besoin | budget | décideur | offre | prochaine étape | échéance | issue | motif',example:'Pour un groupe, demander si le blocage concerne budget, configuration ou date ; proposer une adaptation ciblée après clarification, plutôt qu’une remise immédiate.',owner:'Responsable commercial et relais identifié',sources:['sales']},
 G3:{aim:'Rendre les offres compréhensibles et arbitrer les prix sur la valeur proposée, la demande et les coûts connus.',mechanism:'Une offre trop complexe peut freiner le choix ; une offre attractive peut rester économiquement fragile. Le travail porte sur la cohérence entre promesse, prestation réalisable, prix présenté et coûts effectivement documentés.',causes:['Contenu ou conditions difficiles à comparer.','Prix modifiés sans lecture des coûts.','Offres conçues sans test auprès de la clientèle ciblée.'],questions:['Le client comprend-il ce qui est inclus et les conditions ?','Quels coûts sont connus et lesquels restent à mesurer ?','L’équipe peut-elle réaliser la promesse sur un service chargé ?'],steps:['Relire trois offres avec un regard client : occasion, bénéfice, contenu, conditions, capacité et options ; relever les incompréhensions.','Rapprocher prix et coûts documentés, puis identifier ce qui nécessite une mesure ; distinguer hypothèse de marge et marge vérifiée.','Tester une présentation simplifiée auprès d’un petit nombre de prospects et de l’équipe ; mesurer compréhension, acceptation et faisabilité.'],metric:'Offres avec contenu, conditions et coût documentés ÷ offres examinées × 100. Suivre conversion et retour client avant d’attribuer un effet au prix.',tool:'Offre | cible | bénéfice | contenu | limites | prix | coûts connus | test | retour',example:'Présenter une offre groupe avec une promesse claire, les inclusions et les options ; vérifier en service que le rythme annoncé est réalisable.',owner:'Dirigeant, commercial et responsables de production',sources:['sales','revenue']},
 G4:{aim:'Transformer une bonne expérience ponctuelle en relation suivie et en occasions pertinentes de retour.',mechanism:'La fidélisation commence dans l’expérience vécue et le traitement des irritants. Un avantage ou une relance a peu de valeur si le client ne retrouve pas une expérience cohérente. Le retour effectif doit être distingué d’un simple avis positif.',causes:['Historique des échanges peu exploitable.','Réclamations résolues sans retour au client.','Actions identiques pour des occasions de visite différentes.'],questions:['Qu’est-ce qui motive le retour des clients connus ?','Quel suivi est assuré après un événement ou une réclamation ?','Les actions sont-elles pertinentes pour l’occasion de visite ?'],steps:['Cartographier le parcours : réservation, accueil, service, départ et suivi ; identifier un irritant récurrent et une occasion de retour pertinente.','Tester un suivi après prestation sur un segment limité : recueillir un retour, résoudre un éventuel problème et proposer une prochaine occasion adaptée.','Comparer retours effectifs, réactions négatives et effort mobilisé ; préserver la qualité d’accueil des clients qui ne participent pas au dispositif.'],metric:'Taux de retour observé = clients de la cohorte ayant effectué une nouvelle visite dans la fenêtre définie ÷ clients observables de cette cohorte × 100. Préciser les clients non identifiables.',tool:'Client ou compte | occasion | retour recueilli | problème traité | prochaine occasion | contact autorisé | nouvelle visite',example:'Après un événement d’entreprise, organiser un retour sur l’accueil et le déroulé, puis préparer une prochaine occasion cohérente avec le calendrier du client.',owner:'Responsable relation client, accueil ou commercial',sources:['loyalty']},
 O1:{aim:'Rendre les gestes et les décisions essentiels transmissibles sans transformer le service en succession de formulaires.',mechanism:'Une procédure utile décrit une situation réelle, les étapes critiques et le traitement de l’écart. Un document jamais utilisé ne sécurise pas l’exécution ; l’analyse doit observer sa compréhension et son accessibilité au poste.',causes:['Documents trop longs ou éloignés du travail réel.','Versions différentes selon les postes.','Écarts traités par contournement sans mise à jour.'],questions:['Quelles tâches échouent lorsque la personne expérimentée est absente ?','La procédure est-elle accessible au moment d’agir ?','Comment un écart conduit-il à améliorer le document ?'],steps:['Choisir trois tâches critiques et observer leur réalisation avec l’équipe ; relever les variations et les points qui nécessitent une décision.','Rédiger une fiche courte par tâche : objectif, prérequis, étapes, point de contrôle et conduite à tenir en cas d’écart.','Faire utiliser la fiche par une autre personne et corriger les ambiguïtés ; nommer un responsable de version et de mise à jour.'],metric:'Étapes critiques correctement réalisées ÷ étapes critiques observées × 100. Distinguer absence de moyen, consigne ambiguë et besoin d’accompagnement.',tool:'Situation | prérequis | étapes clés | contrôle | écart | relais | version',example:'Pour une ouverture de bar, vérifier matériel, produits, préparation et point de contrôle avant accueil ; prévoir le relais si un équipement est indisponible.',owner:'Responsable de poste et équipe utilisatrice',sources:['management','prevention']},
 O2:{aim:'Réduire les frictions du service en travaillant les transitions entre accueil, salle, bar et cuisine.',mechanism:'Le délai total dépend de plusieurs transitions et de la charge à chaque poste. Accélérer une étape isolée peut déplacer l’attente ailleurs. Il faut observer le parcours complet et tester un changement limité.',causes:['Commandes ou informations transmises au mauvais moment.','Priorités contradictoires entre postes.','Rôle de coordination insuffisamment défini en période chargée.'],questions:['Où l’attente commence-t-elle réellement et dans quelles situations ?','Qui arbitre les priorités lorsque plusieurs demandes arrivent ensemble ?','La salle, le bar et la cuisine partagent-ils la même lecture de la charge ?'],steps:['Observer deux services contrastés et chronométrer un parcours simple : arrivée, commande, transmission et envoi ; relever contexte et variabilité.','Choisir une friction et coconstruire une règle de transition : qui transmet, à quel moment, avec quelle information et quel accusé de réception.','Tester sur un service comparable puis recueillir les retours de tous les postes ; vérifier que le délai n’a pas simplement été déplacé.'],metric:'Délai médian du parcours choisi, calculé sur plusieurs observations comparables. Compléter par erreurs, retours client et charge signalée par poste.',tool:'Heure | étape | délai | volume en cours | cause observée | coordination | ajustement',example:'Sur une arrivée de groupe, préparer la transmission des commandes au bar par séquence pour éviter un envoi massif sans visibilité sur l’ordre de service.',owner:'Responsable de service avec salle, bar et cuisine',sources:['revenue','management']},
 O3:{aim:'Faire correspondre les compétences et la couverture du planning aux besoins des services, avec des règles lisibles pour l’équipe.',mechanism:'Le nombre de personnes présentes ne suffit pas : compétences, préparation et chevauchement des postes déterminent la capacité réelle. La prévision doit être confrontée à la charge et aux tâches qui ne se voient pas dans le CA.',causes:['Prévisions non actualisées après les réservations.','Compétences ou relais absents sur certains créneaux.','Ajustements tardifs sans analyse des causes.'],questions:['Quelles informations sont utilisées pour construire le planning ?','Quelles compétences doivent être présentes à chaque phase du service ?','Quels écarts reviennent et lesquels étaient réellement imprévisibles ?'],steps:['Comparer deux semaines prévues et réalisées : réservations, événements, couverture des postes et tâches de préparation ou de fermeture.','Définir une couverture par compétence et par créneau, puis organiser une revue des prévisions avant finalisation du planning.','Tester un ajustement limité et recueillir les retours de charge ; conserver une trace des causes d’écart pour améliorer la prévision suivante.'],metric:'Écart d’heures = heures réalisées − heures prévues, sur le même périmètre. Compléter par charge, délais et couverture des compétences essentielles.',tool:'Créneau | activité prévue | compétences nécessaires | couverture | heures prévues | réalisé | cause d’écart',example:'Une réservation de groupe modifie la préparation et la couverture des postes ; revoir ces besoins avant de répartir les mêmes heures habituelles.',owner:'Responsable planning et managers de service',sources:['management','revenue']},
 O4:{aim:'Garantir une expérience régulière à partir de standards concrets, observables et appropriés par l’équipe.',mechanism:'Une promesse de qualité reste abstraite si les comportements attendus ne sont pas explicités. Les écarts peuvent venir d’un manque de repère, de formation ou de moyens ; leur traitement doit distinguer ces situations.',causes:['Standards formulés comme des intentions générales.','Observation centrée sur les erreurs plutôt que les causes.','Attendus incompatibles avec le matériel ou la charge.'],questions:['Quels comportements permettent de reconnaître un service réussi ?','Les salariés disposent-ils des moyens de les réaliser ?','Comment les retours client sont-ils transformés en apprentissage ?'],steps:['Définir avec l’équipe cinq standards observables sur le parcours client : accueil, information, service, traitement d’un incident et départ.','Observer sans interrompre le service, noter les situations et analyser les écarts avec les personnes concernées.','Tester un accompagnement ciblé ou un changement de moyen ; refaire une observation comparable et reconnaître les progrès visibles.'],metric:'Standards respectés ÷ standards observés × 100. Présenter le contexte et la taille de l’échantillon plutôt qu’un classement individuel.',tool:'Standard | comportement attendu | observation | contexte | cause | accompagnement | prochaine observation',example:'Décrire comment accueillir un client en attente et annoncer la suite ; vérifier le comportement réel plutôt que demander uniquement un accueil souriant.',owner:'Responsable qualité de service et managers',sources:['management']},
 S1:{aim:'Clarifier à quoi sert chaque outil et permettre à l’équipe de réaliser les usages essentiels sans contournement.',mechanism:'Un outil peut être disponible sans être compris ou utile au poste. L’enjeu est de relier chaque usage à un responsable, une information de référence et une solution en cas d’indisponibilité.',causes:['Fonctions redondantes ou outils choisis sans besoin défini.','Formation centrée sur les menus plutôt que les situations de travail.','Personne responsable de la mise à jour des usages.'],questions:['Quel outil fait référence pour chaque information ?','Que fait une personne nouvelle pour réaliser une tâche essentielle ?','Comment l’équipe travaille-t-elle si l’outil est indisponible ?'],steps:['Inventorier les usages : réservation, caisse, planning, relation client et suivi ; identifier doublons et besoins non couverts.','Définir un usage de référence par besoin avec responsable et fiche de prise en main fondée sur une situation réelle.','Tester l’usage avec une personne moins expérimentée et prévoir une procédure de secours ; vérifier que les contournements diminuent.'],metric:'Usages essentiels avec outil de référence, responsable et mode de secours ÷ usages essentiels recensés × 100.',tool:'Besoin | outil de référence | information | responsable | accès nécessaire | secours | mise à jour',example:'Préciser où se trouve le brief de groupe validé et comment l’accueil obtient la dernière version sans consulter plusieurs messageries.',owner:'Dirigeant et référents des outils',sources:['management']},
 S2:{aim:'Disposer de chiffres traçables, actualisés et comparables avant de les utiliser pour décider.',mechanism:'Une donnée erronée peut provenir d’un périmètre différent, d’un export incomplet ou d’une définition implicite. La fiabilité doit être vérifiée sur un échantillon et maintenue par une responsabilité explicite.',causes:['Plusieurs chiffres concurrents pour le même indicateur.','Exports incomplets ou périodes non alignées.','Mises à jour dépendantes d’une seule personne.'],questions:['Quelle source fait référence et à quelle date est-elle arrêtée ?','Un tiers peut-il reproduire le calcul à partir des mêmes données ?','Comment les anomalies sont-elles signalées et corrigées ?'],steps:['Choisir trois indicateurs et documenter pour chacun la source, le périmètre, la date de mise à jour et la règle de calcul.','Reproduire les calculs sur une période courte et rapprocher les résultats ; expliquer chaque écart avant d’automatiser.','Attribuer un responsable et une routine de contrôle ; conserver la date et la cause de chaque correction importante.'],metric:'Indicateurs actualisés à la date prévue et calcul reproductible ÷ indicateurs contrôlés × 100. Signaler les données manquantes séparément.',tool:'Indicateur | source | périmètre | formule | date | contrôle | anomalie | correction',example:'Deux exports de CA sont rapprochés en vérifiant HT/TTC, horaires de clôture et activités incluses avant de comparer leurs totaux.',owner:'Référent du suivi et utilisateurs des chiffres',sources:['revenue']},
 S3:{aim:'Réduire les ressaisies utiles uniquement à compenser un manque de circulation de l’information.',mechanism:'Une ressaisie peut être nécessaire pour un contrôle, mais une répétition non maîtrisée crée du temps perdu et des versions divergentes. L’analyse doit préciser l’information d’origine, sa destination et le contrôle réellement utile.',causes:['Sources de référence non définies.','Transfert d’information entre postes sans règle de version.','Connexions automatiques mises en place sans traitement des exceptions.'],questions:['Quelles données sont recopiées et combien de fois par semaine ?','La ressaisie sert-elle un contrôle ou seulement un transfert ?','Quelle source doit faire foi si deux valeurs diffèrent ?'],steps:['Suivre trois flux récurrents et mesurer les ressaisies, corrections et temps mobilisé ; inclure les exceptions.','Choisir un flux fréquent à simplifier par une source commune, un export contrôlé ou une connexion appropriée au besoin.','Tester un cas normal et un cas d’exception ; conserver un contrôle d’échantillon et vérifier la récupération après erreur.'],metric:'Temps hebdomadaire de ressaisie et nombre de corrections sur le flux choisi. Mesurer le même périmètre avant et après, sans inclure d’autres tâches.',tool:'Information | source | destination | fréquence | temps | contrôle utile | exception | solution',example:'Le nombre de participants d’un groupe est partagé depuis le brief validé, au lieu d’être recopié séparément pour l’accueil, le bar et la cuisine.',owner:'Référents des outils et responsables des postes',sources:['management']},
 S4:{aim:'Automatiser une tâche stable et répétitive en gardant un contrôle humain des exceptions et des décisions sensibles.',mechanism:'Une automatisation amplifie aussi les défauts d’un processus mal défini. La première décision porte sur ce qui peut être exécuté de manière fiable et ce qui nécessite encore un jugement ou une relation humaine.',causes:['Processus instable ou règle de déclenchement imprécise.','Absence de contrôle et de responsable des erreurs.','Temps de maintenance oublié dans le bénéfice attendu.'],questions:['Quelle tâche est assez régulière pour être décrite précisément ?','Quelle erreur pourrait atteindre le client ou désorganiser le service ?','Qui reprend la main et comment arrête-t-on le dispositif ?'],steps:['Mesurer fréquence, temps et erreurs de trois tâches ; choisir un cas simple dont les règles et données sont disponibles.','Décrire déclenchement, résultat attendu, contrôle, exceptions et reprise manuelle ; tester hors envoi client avant activation.','Lancer sur un périmètre limité et revoir les erreurs chaque semaine ; mesurer le temps net après contrôle et maintenance.'],metric:'Temps net gagné = temps manuel de référence − temps de contrôle, correction et maintenance. Suivre aussi les erreurs par exécution.',tool:'Déclencheur | données | règle | sortie | contrôle | exception | reprise manuelle | responsable',example:'Préparer automatiquement un rappel interne de dossier à suivre, avec validation humaine du message avant tout envoi au client.',owner:'Dirigeant, référent outil et utilisateur de la tâche',sources:['management']}
};
export function contextualReading(code,evidence){
 const text=String(evidence||'');
 if(code==='H4'&&/informel/i.test(text))return 'La transmission enregistrée comme principalement informelle rend le parcours d’intégration dépendant des personnes présentes. Le travail prioritaire est de rendre explicites les compétences attendues, les étapes d’accompagnement et la vérification de l’autonomie. L’objectif est de soutenir le nouvel arrivant et le référent, plutôt que d’ajouter un contrôle administratif.';
 if(code==='G4'&&/informel/i.test(text))return 'Le suivi de fidélisation enregistré comme informel laisse peu de repères pour organiser une relation après la visite. Cela ne prouve pas une absence de clients fidèles ; cela limite la capacité à comprendre leurs motifs de retour et à reproduire les pratiques utiles. La priorité est de structurer le retour d’expérience et une prochaine occasion pertinente, avant de créer un programme de récompense.';
 if(code==='G2'&&/pas de relance structurée/i.test(text))return 'L’absence de relance structurée renseignée dans le diagnostic laisse les dossiers dépendre du retour spontané du client. Il faut examiner où ils restent ouverts, si le besoin a été clarifié et si une prochaine étape a été convenue.'+(/48\s*h/i.test(text)?' Le délai déclaré supérieur à 48 heures justifie aussi une revue de la prise en charge : mesurer le délai réel, assurer un premier retour utile et attribuer chaque demande à un responsable.':'');
 return '';
}
// Méthodes américaines croisées avec les contraintes CHR ; aucune cause n’est déduite du score seul.
const expertMethods={
 H4:{name:'Autonomie progressive et coaching régulier',reading:'Croiser l’intégration avec le coaching régulier et la sécurité psychologique conduit à vérifier deux dimensions : la maîtrise réelle du poste et la possibilité de demander de l’aide. Une checklist signée ne suffit pas si la personne reste hésitante en service.',steps:['J1 : choisir les compétences essentielles au poste, désigner un référent et démontrer les tâches. Relever les points déjà maîtrisés sans les supposer à partir du CV.','Sur les premiers services : faire pratiquer avec accompagnement, puis observer une réalisation autonome. Tenir un point hebdomadaire court : réussite précise, difficulté, soutien et prochain objectif.','À J30 puis J60 : vérifier les acquis sur des situations adaptées, analyser les difficultés avec le salarié et ajuster le parcours. Pour un extra, appliquer une version courte avant et après son service.'],metric:'Compétences réalisées correctement sans aide ÷ compétences observées × 100. Conserver les compétences encore accompagnées et le ressenti du salarié ; fixer la cible après la première observation.',tool:'Compétence | démonstration | pratique accompagnée | autonomie observée | difficulté exprimée | soutien | prochain point',human:'Inviter explicitement les questions. Décrire une situation et un comportement observé, expliquer son effet puis convenir d’un soutien. Garder une exigence claire et éviter les corrections humiliantes devant les clients ou l’équipe.',sources:['integration','management','coaching']},
 G2:{name:'Vente consultative et prochaine étape convenue',reading:'La vente consultative distingue le besoin exprimé des critères qui feront réellement choisir le client. Croiser cette qualification avec le suivi des devis permet d’examiner si le blocage relève de la pertinence de l’offre, de la décision, du délai ou de la prise en charge. Une relance supplémentaire ne résout pas à elle seule une offre mal adaptée.',steps:['Revoir dix demandes récentes ou toutes celles disponibles : objectif de l’événement, budget annoncé, contraintes, décideur, délai et motif de décision connu. Mesurer aussi la première réponse utile.','Tester une découverte courte : résultat attendu, critères essentiels, contraintes et processus de décision. Reformuler le besoin, proposer une offre argumentée et convenir du canal et de la date du prochain échange.','Chaque semaine, examiner les dossiers arrivés à échéance : prochaine action, responsable, objection et décision. Analyser les refus sans en inventer la cause ; ajuster la proposition avant d’intensifier les relances.'],metric:'Devis acceptés ÷ devis d’une même cohorte × 100, avec dossiers en attente séparés et fenêtre de décision fixe. Suivre aussi délai de réponse utile et marge estimée des offres acceptées ; aucune hausse n’est présumée.',tool:'Demande | besoin | contraintes | décideur | critères de choix | devis | prochaine action et date | responsable | statut | motif confirmé',human:'Le commercial clarifie et conseille. Respecter les préférences de contact, éviter les relances insistantes et vérifier que l’offre vendue peut être exécutée par les équipes dans les conditions annoncées.',sources:['discovery','sales']},
 G4:{name:'Retour client traité et fidélité observée',reading:'Croiser le suivi informel avec la boucle de retour client de Bain et les travaux de Cornell invite à distinguer satisfaction, correction d’un incident et retour effectif. Un client peut être satisfait sans revenir ; une récompense peut attirer une visite sans créer une relation durable. Examiner d’abord les motifs de retour et les obstacles exprimés.',steps:['Examiner les retours et les visites répétées disponibles, sans inventer un historique. Classer les irritants, les raisons de satisfaction et les attentes ; choisir un sujet récurrent à traiter.','Tester une boucle simple : recueillir le retour, attribuer un responsable, répondre au client lorsqu’un suivi est possible et vérifier la correction. Prévoir une prochaine occasion adaptée au motif de visite, sans remise automatique.','Après un mois, revoir les sujets récurrents, les corrections et les retours observables. Comparer des groupes de clients et périodes similaires ; prolonger la mesure si le cycle naturel de visite dépasse le mois.'],metric:'Retours nécessitant une action traités dans le délai convenu ÷ retours concernés × 100. Si un historique fiable existe : clients revenus ÷ clients suivis sur une même période × 100. Indiquer le volume ; le NPS seul ne prouve pas le retour.',tool:'Retour client | motif | responsable | action | délai | réponse | correction vérifiée | retour ultérieur observable',human:'Écouter sans contester immédiatement le ressenti. Confier aux équipes des moyens de correction adaptés et examiner les problèmes récurrents d’organisation avant d’attribuer la responsabilité à une personne.',sources:['feedback','loyalty']}
};
export function expertMethod(code){
 if(expertMethods[code])return expertMethods[code];
 if(/^H/.test(code))return {name:'Sécurité psychologique et coaching régulier',human:'Lors du point hebdomadaire, partir d’une réussite ou d’une difficulté observable, clarifier l’attente et convenir du soutien. Inviter les désaccords utiles et vérifier que les personnes peuvent demander de l’aide sans être humiliées.',sources:['management','coaching']};
 if(/^G/.test(code))return {name:'Découverte du besoin et suivi de la relation client',human:'Qualifier l’objectif, les contraintes et les critères de choix avant de conseiller. Reformuler, convenir d’une prochaine étape et utiliser les retours clients pour corriger l’offre ou son exécution.',sources:['discovery','feedback']};
 if(/^P/.test(code))return {name:'Gestion du revenu adaptée à la restauration',human:'Analyser les périodes, le panier et l’utilisation de la capacité. Lorsque les données le permettent, calculer le revenu par place disponible et par heure : CA du créneau ÷ (places disponibles × heures). Vérifier aussi la marge, la satisfaction et la charge ; cet indicateur n’est pas une mesure de bénéfice.',sources:['revenue']};
 return {name:'Test progressif PDSA : prévoir, essayer, observer, ajuster',human:'Définir une amélioration attendue et une mesure initiale ; tester sur un service ou un flux. Recueillir les écarts et le retour de l’équipe, puis décider de maintenir, modifier ou arrêter avant extension.',sources:['improvement']};
}
export function consultingGuide(code){const base=profiles[code];if(base){const method=expertMethod(code);return {...base,...(method.reading?{mechanism:method.reading,steps:method.steps,metric:method.metric,tool:method.tool}:{}),method,sources:[...new Set([...method.sources,...(method.reading?[]:base.sources)])]};}return {aim:'Transformer la priorité retenue en une amélioration observable, adaptée aux moyens du lieu.',mechanism:'Cette priorité ne dispose pas d’un critère associé. Le consultant doit préciser le périmètre et les éléments qui la justifient avant de conclure sur les causes.',causes:['Rôle ou périmètre à préciser.','Moyens et contraintes à examiner.','Pratique ou règle de fonctionnement à vérifier.'],questions:['Quelle situation concrète justifie cette priorité ?','Quels éléments permettent de distinguer cause et conséquence ?','Qui devra participer au test de la solution ?'],steps:['Décrire une situation réelle et relever les éléments disponibles, les acteurs et les contraintes.','Concevoir avec les personnes concernées un test limité avec objectif, responsable et date de revue.','Observer le résultat, recueillir les retours et décider de maintenir, modifier ou arrêter le test.'],metric:'Définir un indicateur, une source, un périmètre et une période de référence avant le test.',tool:'Situation | hypothèse | test | responsable | mesure | décision',example:'Choisir un service ou un dossier représentatif, puis comparer la pratique actuelle et la pratique testée sur un périmètre similaire.',owner:'Dirigeant et responsable de la priorité',sources:['management']};}
const paragraph=s=>`<p>${esc(s)}</p>`;
const list=items=>`<ul class="auditList">${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
function section(label,content){return `<div class="auditSection"><h3>${label}</h3>${content}</div>`;}
function page(d,n,eyebrow,title,content){return `<section class="reportPage auditPage"><div class="eyebrow">${esc(eyebrow)}</div><h2>${esc(title)}</h2>${content}<div class="reportNo">Hospitality Performance · ${esc(d.establishment_name)} · ${n}/9</div></section>`;}
export function consultingReport(d,criteria,scores,priorities,ready,dimensions,date){
 const summary=scoreSummary(scores),selected=[1,2,3].map(rank=>priorities.find(p=>Number(p.rank)===rank)||{rank,title:'Priorité à compléter',finding:'',action:'',success_indicator:''});
 const draft=diagnosticDraft(d,criteria,scores),legacy=legacyDiagnosticDraft(d,criteria,scores);
 const autoSummary=[draft?.client_summary,legacy?.client_summary].includes(d.client_summary);
 const selectedReading=selected.map(p=>{const s=scores.find(s=>s.criterion_code===p.criterion_code);return s?(contextualReading(p.criterion_code,s.observed_evidence||s.auto_evidence)||consultantFinding(p.criterion_code,s.score)):p.finding;}).filter(Boolean).join(' ');
 const executive=autoSummary?`${d.establishment_name} obtient ${summary.score??summary.provisional??'—'}/100. ${selectedReading}`:d.client_summary;
 let html=`<div class="report" id="reportDocument"><section class="reportPage reportCover"><div><div class="reportBrand">HP</div><div>Hospitality Performance</div></div><div><div class="eyebrow">Diagnostic approfondi · Trois priorités</div><h1>Rapport de<br>diagnostic</h1><div class="reportName">${esc(d.establishment_name)}</div><p>${esc(d.establishment_type||'Établissement CHR')} · ${date(d.created_at)}</p><div class="coverScope">Analyse des pratiques · Recommandations opérationnelles · Feuille de route à 90 jours</div></div><div class="coverQuote"><p>« Il n’est de richesse que d’hommes. »</p><span>Jean Bodin</span></div></section>`;
 html+=page(d,2,'01 · Synthèse et périmètre','Votre diagnostic et les choix retenus',`<div class="scoreHero"><div><strong>${summary.score??summary.provisional??'—'}</strong><small>/100</small></div><span class="pill">${ready?'Diagnostic validé':'Score provisoire'}</span></div>${dimensions()}${section('Lecture du consultant',`<div class="textBlock">${esc(executive||'Synthèse à compléter.')}</div>`)}${section('Points d’appui',`<div class="textBlock">${esc(d.strengths||'À préciser avec le consultant.')}</div>`)}${section('Trois priorités sélectionnées',list(selected.map(p=>`${p.rank}. ${p.title}`)))}<div class="auditCallout"><b>Ce qui est évalué</b><p>${summary.count}/20 critères renseignés ; ${summary.reviewed}/20 vérifiés. Le score mesure la maturité des pratiques, sans audit financier, juridique ou réglementaire. Les notes donnent une orientation ; elles ne prouvent ni une perte de marge ni la cause d’un dysfonctionnement.</p><p>Les analyses suivantes distinguent les éléments enregistrés, leur interprétation et les hypothèses à vérifier. Les protocoles proposés sont des adaptations HP ; ils nécessitent un échange terrain avant engagement des moyens.</p></div>`);
 selected.forEach((p,i)=>{
  const s=scores.find(s=>s.criterion_code===p.criterion_code),c=criteria.find(c=>c.code===p.criterion_code),g=consultingGuide(p.criterion_code),evidence=s?.observed_evidence||s?.auto_evidence||'Aucun élément de preuve n’a été enregistré pour cette priorité.';
  const interpretation=s?consultantFinding(p.criterion_code,s.score):'Le consultant doit préciser la lecture de cette priorité et les éléments qui la justifient.';
  const legacyFinding=legacy?.priorities.find(row=>row.criterion_code===p.criterion_code)?.finding;
  const rawFinding=[s?.observed_evidence,s?.auto_evidence,legacyFinding].filter(Boolean).includes(p.finding);
  const context=contextualReading(p.criterion_code,evidence);
  const conclusion=rawFinding?(context||interpretation):(p.finding||context||interpretation);
  html+=page(d,3+i*2,`Priorité ${i+1} · Analyse`,p.title||'Priorité à compléter',`<div class="auditMeta">${esc(c?.label||'Priorité libre')} · ${s?esc(s.score)+'/5 · '+esc(s.evidence_source):'Critère associé à préciser'}</div>${section('Conclusion retenue pour l’établissement',`<div class="textBlock">${esc(conclusion)}</div>`)}${section('Éléments enregistrés et solidité du constat',paragraph(evidence)+paragraph(s?.evidence_source==='Déclaration dirigeant'?'La source est déclarative. La vérification consultant confirme la revue du critère ; elle ne remplace pas une observation ou une pièce. Les effets réels doivent être corroborés.':s?.evidence_source==='Observation consultant'?'Le constat repose sur une observation consultant. Il faut conserver le contexte, la date et les situations observées avant de généraliser à tous les services.':'La source doit rester traçable : nature de l’élément, période et périmètre. La présence d’un document ne démontre pas seule l’application de la pratique.'))}${section('Lecture approfondie et enjeu opérationnel',(context&&context!==conclusion?paragraph(context):'')+paragraph(g.mechanism))}${section('Causes possibles à confronter au terrain',list(g.causes))}${section('Trois questions pour confirmer le diagnostic',list(g.questions))}<div class="auditCallout"><b>Résultat recherché</b>${paragraph(g.aim)}<p>Observer au moins une situation courante et une situation de charge différente. Recueillir le point de vue des personnes concernées et noter les explications alternatives avant de retenir une cause.</p></div>`);
  html+=page(d,4+i*2,`Priorité ${i+1} · Mise en œuvre`,'Méthode, outils et suivi',`${section('Action décidée et pilote proposé',paragraph(p.action||actionSuggestions[p.criterion_code]?.[1]||'Action à définir.')+paragraph(`Pilote proposé : ${g.owner}. Le dirigeant confirme le nom du responsable, son temps disponible et les moyens nécessaires avant le lancement.`))}<div class="auditSteps">${g.steps.map((text,k)=>`<div><span class="auditStepLabel">${['J1 à J15 · Comprendre','J16 à J30 · Tester','J31 à J60 · Stabiliser'][k]}</span>${paragraph(text)}</div>`).join('')}</div>${section('Outil de travail à mettre en place',paragraph('Trame proposée à renseigner sur un seul support partagé, avec une date et un responsable de mise à jour :')+`<div class="auditTool">${esc(g.tool)}</div>`)}${section('Mesurer le résultat sans surestimer l’impact',paragraph(`Indicateur retenu : ${p.success_indicator||'à préciser'}.`)+paragraph(g.metric)+paragraph('Relever une situation de référence avant le test. La cible chiffrée est fixée après cette mesure, selon les moyens disponibles. Comparer des périodes et périmètres similaires ; conserver le volume observé et les événements exceptionnels.'))}${section('Exemple d’application CHR',paragraph(g.example))}<div class="auditCallout"><b>${esc(g.method?.name||'Test progressif et apprentissage')}</b>${paragraph(g.method?.human||'Définir une mesure initiale, tester sur un périmètre limité et recueillir le retour des personnes concernées avant extension.')}<p>Adaptation HP : vérifier les résultats et les effets sur la charge avant de généraliser.</p></div><p class="auditSource">Repères : ${g.sources.map(key=>esc(consultingSources[key].title.split(' · ')[0])).join(', ')}. Références et limites en page 9.</p>`);
 });
 const sourceKeys=[...new Set([...selected.flatMap(p=>consultingGuide(p.criterion_code).sources),'improvement'])];
 html+=page(d,9,'03 · Piloter la suite','Feuille de route et repères méthodologiques',`${section('Arbitrages à prendre lors de la restitution',paragraph('Confirmer les priorités, les pilotes et l’ordre des tests. Cycle PDSA : prévoir un résultat et une mesure, essayer à petite échelle, observer puis ajuster. Tester une modification à la fois ; noter les changements de saison et d’équipe.'))}<table class="auditRoadmap"><thead><tr><th>Échéance</th><th>Décision et preuve attendue</th></tr></thead><tbody><tr><td>J15</td><td>Situation de référence établie, causes examinées et moyens confirmés pour chaque priorité.</td></tr><tr><td>J30</td><td>Premier test réalisé ; retour de l’équipe et du client si pertinent ; décision de poursuivre, modifier ou arrêter.</td></tr><tr><td>J60</td><td>Pratique stabilisée sur le périmètre retenu ; outil renseigné et indicateur mis à jour par son responsable.</td></tr><tr><td>J90</td><td>Bilan des résultats et de la charge. Conserver le score initial ; réévaluer les mêmes critères avec des preuves actualisées, sans progression présumée.</td></tr></tbody></table>${section('Critères de décision à J90',list(['La pratique peut être appliquée et expliquée par les personnes concernées, même en l’absence de son initiateur.','L’indicateur est reproductible et l’écart observé est discuté avec le contexte ; aucun gain financier n’est supposé sans données.','Les retours de charge et de qualité restent acceptables. Un résultat insuffisant conduit à revoir le test ou la cause retenue.']))}${section('Sources et portée des recommandations',`<p>Sources consultées le 04/10/2026. Les protocoles, outils et exemples sont des adaptations HP ; les études et guides ne garantissent pas leur efficacité locale.</p><div class="auditReferences">${sourceKeys.map(key=>{const ref=consultingSources[key];return `<div><a href="${ref.url}" target="_blank" rel="noopener">${esc(ref.title)}</a>${paragraph(ref.principle)}</div>`;}).join('')}</div>`)}`);
 return html+'</div>';
}
